export interface Claim {
  id: number;
  /** When the claim was added, in the order claims and forward-only rates are saved (see Rate.forwardAfter). */
  addedSeq?: number | null;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  /** The claim's number on the sheet, given when settled or approved; null before then (unless numbered when opened, under the old rule). Sheet-wide (1, 2, ...), or
   *  under numbering per period <period name>-<n>, or X-<n> in no period. */
  number: string | null;
  /** The due fixed when the claim was settled; null while not settled or if its grade then had no rate. */
  settledDue: string | null;
  /** The user who opened the claim; null while DRAFT, or if voided without being opened. */
  openedBy: string | null;
  /** The user who last edited the claim through its form or its row's amount; null while never edited. */
  editedBy: string | null;
  /** Whether the person's last statement bound the claim to the figure it had then. */
  stated: boolean;
  /** The figure bound by the last statement; null while unbound or if it had no rate then. */
  statedDue: string | null;
  /** The due as shown when the last statement bound the claim, late charge included; null while unbound or if it had no rate then. */
  statedCharged: string | null;
  /** The number of the claim this correction corrects; null for a claim that is not a correction. */
  corrects: string | null;
  /** The claim's external reference, unique on the sheet without regard to case; null when none. */
  ref: string | null;
  /** The claim's tags: trimmed, lower-cased, without repeats and sorted; empty when it has none. */
  tags: string[];
  /** The date the claim is due by, fixed when it was added. */
  dueBy: string;
  /** The claim's status log, oldest first: who moved it to each status, on the sheet's today then,
   *  with its due as computed at that moment. */
  log: ClaimLogLine[];
  /** The date the claim is deferred until; null when it was never deferred. */
  deferredUntil: string | null;
  /** How many proofs the claim has. */
  proofs: number;
  /** How many of its proofs are receipts. */
  proofsReceipt: number;
  /** How many of its proofs are photos. */
  proofsPhoto: number;
  /** The number of the claim this claim was split off from; null for a claim not made by a split. */
  splitFrom: string | null;
  /** The user whose open editor locks the claim for everyone else; null when unlocked. */

/** Whether a claim is open: OPEN or PENDING. Only an open claim goes overdue. */
export function isOpen(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'PENDING';
}

/** Whether a claim is deferred on the sheet's today: open, and its deferral date not yet reached. */
/** Whether a REVIEW claim is late for review on the sheet's today: its review day plus the review SLA
 *  (whole days; blank: none) is before today. */
export function reviewLate(c: Claim, today: string | null, sla: string): boolean {
  return c.status === 'REVIEW' && c.reviewOn !== null && today !== null && sla !== ''
    && plusDays(c.reviewOn, Number(sla)) < today;
}

/** Whether a PENDING claim is late pending on the sheet's today: its pending day plus the pending SLA
 *  (whole days; blank: none) is before today. */
export function pendingLate(c: Claim, today: string | null, sla: string): boolean {
  return c.status === 'PENDING' && c.pendingOn !== null && today !== null && sla !== ''
    && plusDays(c.pendingOn, Number(sla)) < today;
}

export function deferred(c: Claim, today: string | null): boolean {
  return isOpen(c) && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
}

/** The refusal of a change to a claim dated inside a closed period. */
const CLOSED = 'That date is inside a closed period.';

/** The refusal of editing a claim another user's open editor locks (or no longer a DRAFT). */
const LOCKED = 'Another user is editing this claim, or it is no longer a DRAFT.';


    /** {@code lastBatch}: the sheet's last settle batch number after the bulk settle; none when there has been none. */
    public record BulkSettleResponse(int settled, int refused, List<ClaimResponse> claims, Integer lastBatch) {
    }

    public record ClaimResponse(long id, long personId, String amount, LocalDate date, String note,
            ClaimStatus status, String number, String settledDue, String openedBy,
            String editedBy,
            boolean stated, String statedDue, String corrects, LocalDate dueBy, List<ClaimLogLine> log,
            LocalDate deferredUntil, int proofs, String splitFrom, String lockedBy,
            boolean lateEntry, LocalDate remindedOn, String ref, List<String> tags, String voidReason,
            List<ClaimCommentLine> comments, Integer batch, List<ClaimLineLine> lines, Long addedSeq,
            LocalDate reviewOn, boolean waived, String statedCharged, int proofsReceipt, int proofsPhoto,
            boolean held, List<ClaimShareLine> shares, String reviewAssigned, LocalDate pendingOn) {
    }

    /** One of the people a claim is shared with, in the order added: the holder's id and their share. */
    public record ClaimShareLine(long holder, String share) {
    }

    /** One line of a claim, in the order added: its label, quantity and unit amount. */
    public record ClaimLineLine(String label, int qty, String unit) {
    }

    /** One comment on a claim, oldest first. */
    public record ClaimCommentLine(String by, LocalDate date, String text) {
    }

    /** One line of a claim's status log, oldest first. */
    public record ClaimLogLine(ClaimStatus status, String by, LocalDate date, String due) {
    }

    private static String money(BigDecimal value) {
        return value == null ? null : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
    }

    public static ClaimResponse response(Claim claim) {
        return new ClaimResponse(claim.getId(), claim.getPersonId(),
                claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(), claim.getDate(),
                claim.getNote(), claim.getStatus(), claim.getNumber(),
                money(claim.getSettledDue()), claim.getOpenedBy(), claim.getEditedBy(), claim.isStated(), money(claim.getStatedDue()),
                claim.getCorrects(), claim.getDueBy(),
                claim.getLog().stream().map(l -> new ClaimLogLine(l.getStatus(), l.getBy(), l.getDate(), l.getDue()))
                        .toList(),
                claim.getDeferredUntil(), claim.getProofs(), claim.getSplitFrom(), claim.getLockedBy(),
                claim.isLateEntry(), claim.getRemindedOn(), claim.getRef(), claim.getTags(),
                claim.getVoidReason(),
                claim.getComments().stream().map(c -> new ClaimCommentLine(c.getBy(), c.getDate(), c.getText()))
                        .toList(),
                claim.getBatch(),
                claim.getLines().stream().map(l -> new ClaimLineLine(l.getLabel(), l.getQty(), money(l.getUnit())))
