test("deferred bound counts scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "clerk-limit", "1.50");
  await ui.setSetting(pg_uma, "terms", "10");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "perm-open", "clerk");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  expect(await ui.addHoliday(pg_uma, "2026-03-24")).toBe(true);
  expect(await ui.addHoliday(pg_uma, "2026-04-03")).toBe(true);
  await ui.setSetting(pg_uma, "grace-C", "2");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "4.00"}));
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  await ui.setSetting(pg_uma, "alert-threshold", "1.00");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-01", "half-up")).toBe(true);
  await ui.setSetting(pg_uma, "review-threshold", "4.00");
  await ui.setSetting(pg_uma, "clerk-limit-B", "9.00");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "7.50", "from": "2026-03-01"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "C", "terms": "20"})).toBeNull();
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "tags": "b, a"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "12.50", "start": "2026-02-20", "end": "2026-04-30", "day": "15"}));
  expect(await ui.pasteClaims(pg_uma, "Ada,25.00,2026-03-01,paste\nCam,12.50,2026-03-05,paste")).toBe(2);
  const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
  const c_cam_0 = await ui.claimAt(pg_uma, p_cam, 0);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.pasteClaims(pg_vic, "Ada,7.77,,\nCam,3.33,2026-03-28,paste\nCam,25.00,,a, b")).toBeNull();
  await ui.setToday(pg_vic, "2026-03-26");
  expect(await ui.editPerson(pg_vic, p_ada, {"grade": "A", "gradeFrom": "2026-03-09"})).toBe(true);
  expect(await ui.statement(pg_vic, p_cam)).toBe(true);
  expect(await ui.periodAction(pg_vic, "2026-03", "soft-close")).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("25.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("5.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("5.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("12.50");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_vic.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("yes");

